<?php get_header(); ?><main id="content" class="container section"><h1><?php is_home() ? print 'Bài viết mới' : single_post_title(); ?></h1><div class="article-grid"><?php if(have_posts()): while(have_posts()): the_post(); ?><article class="article-card"><a href="<?php the_permalink(); ?>"><?php if(has_post_thumbnail()) the_post_thumbnail('medium_large'); ?></a><div class="article-content"><small><?php echo esc_html(get_the_date('d/m/Y')); ?></small><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(get_the_excerpt()); ?></p></div></article><?php endwhile; else: ?><p>Chưa có bài viết nào.</p><?php endif; ?></div><div class="pagination"><?php the_posts_pagination(); ?></div></main><?php get_footer(); ?>
